const locations={6000:['Perth','WA','Western Australia'],6160:['Fremantle','WA','Western Australia'],2000:['Sydney','NSW','New South Wales'],3000:['Melbourne','VIC','Victoria']};
const names=['ghost.exe','westside','blinkdagger','mango season','deadset','offlane enjoyer','nightshift','river rat','mid or feed','smokescreen','highground','no worries','pixelpilot','last hit','dropbear','overtime','stacked','headshot'];
let players=names.map((name,i)=>({name,postcode:i<8?'6000':i<11?'6160':i<15?'2000':'3000',dota:7240-i*187,cs:24100-i*621,win:Math.round(64-i*.8),matches:52+i*7,trend:i%4===2?-2:1+i%3,form:i%3===0?'WWLWW':i%3===1?'WLWLW':'LWWLL'}));
let game='dota',scope='postcode',home='6000',profile;try{profile=JSON.parse(localStorage.getItem('localrival-profile'))}catch{}const $=id=>document.getElementById(id), modal=$('modal');
function show(html){$('modalBody').innerHTML=html;modal.showModal()}document.querySelector('.close').onclick=()=>modal.close();modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
function render(){const loc=locations[home];let data=players.filter(p=>scope==='country'||(scope==='state'?locations[p.postcode][1]===loc[1]:scope==='city'?locations[p.postcode][0]===loc[0]:p.postcode===home));const score=p=>p[game];const top=[...data].sort((a,b)=>score(b)-score(a))[0];$('place').textContent=scope==='postcode'?`${loc[0]} ${home}`:scope==='city'?loc[0]:scope==='state'?loc[2]:'Australia';$('area').textContent=scope==='country'?'National sample community':`${loc[2]}, Australia`;$('count').textContent=data.length;$('best').textContent=top?score(top).toLocaleString()+' '+(game==='dota'?'MMR':'rating'):'—';$('leader').textContent=top?'Held by '+top.name:'No ranked players yet';$('boardTitle').textContent=({postcode:'Postcode',city:'City / town',state:'State',country:'National'})[scope]+' contenders';$('scoreTitle').textContent=game==='dota'?'DEMO MMR':'DEMO CS RATING';data.sort((a,b)=>$('sort').value==='win'?b.win-a.win:score(b)-score(a));const ranked=data.map((p,i)=>({p,rank:i+1})).filter(({p})=>p.name.toLowerCase().includes($('search').value.toLowerCase()));$('rows').replaceChildren();ranked.forEach(({p,rank})=>{const tr=document.createElement('tr');tr.tabIndex=0;tr.innerHTML=`<td class="rank ${rank<4?'top':''}">${String(rank).padStart(2,'0')}</td><td><div class="player"><span class="avatar">${p.name.slice(0,2).toUpperCase()}</span><div><b>${p.name}</b><small>${locations[p.postcode][0]} · ${p.postcode}</small></div></div></td><td class="rating">${score(p).toLocaleString()}</td><td>${p.win}%</td><td>${p.matches}</td><td><div class="form">${[...p.form].map(f=>`<span class="${f==='L'?'loss':''}">${f}</span>`).join('')}</div></td><td class="${p.trend>0?'up':'down'}">${p.trend>0?'↗':'↘'} ${Math.abs(p.trend)}</td>`;tr.onclick=()=>show(`<div class="eyebrow">SAMPLE PLAYER PROFILE</div><h2>${p.name}</h2><p>${locations[p.postcode][0]} · ${p.postcode} · ${locations[p.postcode][1]}</p><h2>${score(p).toLocaleString()} ${game==='dota'?'MMR':'CS rating'}</h2><p>${p.win}% win rate · ${p.matches} sample matches<br>Recent form: ${p.form.split('').join(' · ')}</p><p>This is fictional demonstration data. Live match history and account verification are not connected.</p>`);tr.onkeydown=e=>{if(e.key==='Enter')tr.click()};$('rows').append(tr)});if(!ranked.length)$('rows').innerHTML='<tr><td colspan="7">No players found. Try another name or area.</td></tr>';$('resultCount').textContent=`${ranked.length} of ${data.length} players · Demo ratings`}
document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{game=b.dataset.game;document.querySelectorAll('[data-game]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelectorAll('[data-scope]').forEach(b=>b.onclick=()=>{scope=b.dataset.scope;document.querySelectorAll('[data-scope]').forEach(x=>x.classList.toggle('active',x===b));render()});$('location').onchange=e=>{home=e.target.value;render()};$('search').oninput=render;$('sort').onchange=render;
function join(){show('<div class="eyebrow">REP YOUR HOME GROUND</div><h2>Your local story starts here.</h2><p>Create a demo profile on this device. Your postcode is self-declared; no street address is requested.</p><form id="joinForm"><label for="alias">PLAYER NAME</label><input id="alias" required maxlength="24" placeholder="Your gaming alias"><label for="postcode">HOME POSTCODE</label><select id="postcode">'+Object.entries(locations).map(([k,v])=>`<option value="${k}">${k} · ${v[0]}</option>`).join('')+'</select><button class="primary">Save demo profile</button></form>');$('joinForm').onsubmit=e=>{e.preventDefault();profile={name:$('alias').value.trim(),postcode:$('postcode').value};if(!profile.name)return;$('alias').setCustomValidity('');localStorage.setItem('localrival-profile',JSON.stringify(profile));modal.close();myProfile()}}
function myProfile(){if(!profile)return join();show('<div class="eyebrow">YOUR DEMO PROFILE</div><h2 id="safeName"></h2><p>'+locations[profile.postcode][0]+' · '+profile.postcode+'</p><p>Unranked — no verified matches yet.</p><p>A live pilot will need Steam account verification, an agreed game-data provider, location checks and a minimum match requirement.</p><button class="primary" id="editProfile">Edit profile</button>');$('safeName').textContent=profile.name;$('editProfile').onclick=join}
function rules(){show('<div class="eyebrow">A FAIR HOME GROUND</div><h2>How the ladder works</h2><p>This prototype uses fictional players and ratings to test local discovery. Rankings are separate for each game.</p><ul><li>Postcode → city / town → state → country.</li><li>Demo Dota 2 players sort by sample MMR; CS players by sample CS rating.</li><li>Trend and recent form are sample values.</li><li>Demo profiles stay on this device and remain unranked.</li></ul><p>Before a live season: choose an available rating source, verify account ownership, validate postcode claims, set minimum matches and inactivity rules, and define safeguards for small communities. Exact addresses should never be displayed.</p>')}
$('joinTop').onclick=join;$('joinCard').onclick=join;$('profileNav').onclick=myProfile;$('rulesNav').onclick=rules;$('rulesFooter').onclick=rules;$('rankNav').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});render();
